#pragma once

// The C++ interop API of the Python modules generated by `mrbind_gen_python`:
//   lets an extension module written in C++ accept and return the objects of such a module.
// Get it with `PyCapsule_Import("<module qualname>.__mrbind_cpp_api__", 0)`.
// The types are named by the C++ spellings that the bindings use (e.g. `MR::Mesh`, `MR::Vector3f`).
// The extension must use the same C++ standard library as the C bindings, since the shared pointers are passed directly.

#include <Python.h>

namespace mrbind_py
{
    // Must match `CppApi` in the runtime of `mrbind_gen_python`.
    struct CppApi
    {
        int version; // 1.

        // The C++ object of `obj`, which must be an instance of the class of `cpp_type` or of a class derived from it.
        // Returns null with a `TypeError` set otherwise.
        void *(*unwrap)(PyObject *obj, const char *cpp_type);

        // A `const std::shared_ptr<const void> *` owning the object of `obj` (owned by `obj`, valid while it's alive),
        //   making one if `obj` owns its object. Null without an error if the object isn't owned by `obj`.
        const void *(*get_holder)(PyObject *obj);

        // A new reference to an instance of the class of `cpp_type` for `ptr` (`None` if `ptr` is null).
        // If `owned`, it takes `ptr`, which must be allocated with `new`; otherwise it keeps `owner` alive, if not null.
        // Returns null with an error set on failure.
        PyObject *(*wrap)(const char *cpp_type, void *ptr, int owned, PyObject *owner);

        // Same, sharing the ownership: `holder` is a `new std::shared_ptr<const void>` owning `ptr`, consumed even on failure.
        PyObject *(*wrap_shared)(const char *cpp_type, void *ptr, void *holder);
    };

    [[nodiscard]] inline const CppApi *ImportCppApi(const char *capsule_name)
    {
        return static_cast<const CppApi *>(PyCapsule_Import(capsule_name, 0));
    }
}
